+/// Applies the matrix to the low `len` limbs of `f` and `g`, dividing exactly
+/// by `2^62`. Limb `len - 1` carries the sign and higher limbs are zero.
+#[inline(always)]
+fn update_fg(f: &mut Signed62, g: &mut Signed62, len: usize, t: [i64; 4]) {
+    let [u, v, q, r] = t.map(i128::from);
+    let mut cf = u * f[0] as i128 + v * g[0] as i128;
+    let mut cg = q * f[0] as i128 + r * g[0] as i128;
+    cf >>= 62;
+    cg >>= 62;
+    for i in 1..len {
+        cf += u * f[i] as i128 + v * g[i] as i128;
+        cg += q * f[i] as i128 + r * g[i] as i128;
+        f[i - 1] = (cf as i64) & M62;
+        g[i - 1] = (cg as i64) & M62;
+        cf >>= 62;
+        cg >>= 62;
+    }
+    f[len - 1] = cf as i64;
+    g[len - 1] = cg as i64;
+}

